using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "OnlySpecificChestRunModifier", menuName = "Data/RunModifiers/OnlySpecificChestRunModifier", order = 0)]
public class OnlySpecificChestRunModifier : RunModifier
{
	private const string onlySpecificChestRunModifierBaseID = "OnlySpecificChestRunModifierBase";

	[Header("Specifics")]
	[SerializeField]
	private DiceClearingReward diceClearingReward;

	[SerializeField]
	private DiceTier diceTier;

	public DiceClearingReward DiceClearingReward => diceClearingReward;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.OnlySpecificChestRunModifier = this;
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = diceClearingReward.Rewards.DuplicateAsList();
		List<Reward> list2 = nonModifiedRewards.DuplicateAsList();
		int num = list2.Count((Reward item) => item is DiceReward);
		if (num == 0)
		{
			return nonModifiedRewards;
		}
		int num2 = list2.FindIndex((Reward item) => item is DiceReward);
		list2[num2] = list.PopFirst();
		switch (num)
		{
		case 2:
			if (list.Count > 0)
			{
				list2[num2 + 1] = list.PopFirst();
			}
			else
			{
				list2.RemoveAt(num2 + 1);
			}
			break;
		case 1:
			if (list.Count > 0)
			{
				list2.Insert(num2, list.PopFirst());
			}
			break;
		}
		return list2.ToArray();
	}

	public override string GetLocalizedDescription()
	{
		return Smart.Format(base.localizationManager.GetLocalizedString("OnlySpecificChestRunModifierBase"), diceTier.GetLocalizedDiceTierWithDie());
	}
}
